// Traduz o envelope MQTT (formato de new-program/mqtt-maquina.js)
// em escrita Modbus no CLP. Hoje so MESA_START/MESA_STOP tem acao
// fisica mapeada (escreve %MW2, que ja esta OR'ado no ladder com o
// botao fisico I0.7 -> %M3 -> %Q0.2). Outros comandos (ex.:
// MOVER_PONTO) nao tem acao fisica ainda porque o CLP nao tem sensor
// de posicao -- a producao continua simulada no site.
// Mapa completo em node-red/README.md.

let dados;
try {
    dados = JSON.parse(msg.payload);
} catch (erro) {
    node.warn("Comando MQTT invalido (nao e JSON), ignorado: " + msg.payload);
    return null;
}

if (dados.comando === "MESA_START") {
    msg.payload = [1];
    return msg;
}

if (dados.comando === "MESA_STOP") {
    msg.payload = [0];
    return msg;
}

node.log(`Comando "${dados.comando}" ignorado pela ponte (sem acao fisica mapeada ainda).`);
return null;

// Traduz os registradores lidos do CLP (%MW10 = status empacotado em
// bits, %MW11 = heartbeat) para o formato que
// new-program/novoprograma.js ja sabe interpretar (evento STATUS com
// subindo/descendo/mesaGirando/limiteBaixo/limiteCima/emergencia).
// Mapa completo em node-red/README.md.

const regs = msg.payload;

if (!Array.isArray(regs) || regs.length < 2) {
    return [null, null];
}

const status = regs[0];

const emergencia = Boolean(status & 0x20);

const payload = {
    tipo: "STATUS",
    subindo: Boolean(status & 0x01),
    descendo: Boolean(status & 0x02),
    mesaGirando: Boolean(status & 0x04),
    limiteBaixo: Boolean(status & 0x08),
    limiteCima: Boolean(status & 0x10),
    emergencia,
    timestamp: Date.now(),
};

const msgStatus = {
    topic: "soldatech/maquina/status",
    payload: JSON.stringify(payload),
};

// So publica ERRO na borda de subida da emergencia (nao fica
// repetindo a cada 300ms enquanto ela estiver ativa).
const emergenciaAnterior = flow.get("emergenciaAnteriorClp") || false;
flow.set("emergenciaAnteriorClp", emergencia);

let msgErro = null;
if (emergencia && !emergenciaAnterior) {
    msgErro = {
        topic: "soldatech/maquina/erro",
        payload: JSON.stringify({
            tipo: "ERRO",
            codigo: "CLP_EMERGENCIA",
            mensagem: "Botao de emergencia acionado no CLP.",
        }),
    };
}

return [msgStatus, msgErro];
